class MapSum {
    private int[][] children;
    private int[] prefixSum;
    private int cnt;
    private java.util.HashMap<String, Integer> map;

    public MapSum() {
        children = new int[2501][26];
        prefixSum = new int[2501];
        cnt = 1;
        map = new java.util.HashMap<>();
    }

    public void insert(String key, int val) {
        int delta = val - map.getOrDefault(key, 0);
        map.put(key, val);
        int node = 0;
        for (char c : key.toCharArray()) {
            int idx = c - 'a';
            if (children[node][idx] == 0) {
                children[node][idx] = cnt++;
            }
            node = children[node][idx];
            prefixSum[node] += delta;
        }
    }

    public int sum(String prefix) {
        int node = 0;
        for (char c : prefix.toCharArray()) {
            int idx = c - 'a';
            if (children[node][idx] == 0) return 0;
            node = children[node][idx];
        }
        return prefixSum[node];
    }
}

import java.util.*;

class MapSum {
    private Map<String, Integer> map;

    public MapSum() {
        map = new HashMap();
    }

    public void insert(String key, int val) {
        map.put(key, val);
    }

    public int sum(String prefix) {
        int total = 0;
        Iterator<Map.Entry<String, Integer>> it = map.entrySet().iterator();
        while (it.hasNext()) {
            Map.Entry<String, Integer> entry = it.next();
            if (entry.getKey().startsWith(prefix)) {
                total += entry.getValue().intValue();
            }
        }
        return total;
    }
}
